//! Fixed attempts for draws generated by a resolving leaf.

mod legacy;
pub(crate) use legacy::requires_generator_receipt;
#[cfg(feature = "eternal-fixtures")]
pub(crate) use legacy::visit_attempts;

use super::{
    draw_won_game, start_instruction, validate_native_progress, InstructionV1, JournalV1,
    ProgressV1, SourceV1,
};
use crate::effect::{
    occult_draw_root, EffectAnsweredChoiceGuard, EffectContinuation, EffectFrame,
    EffectTargetSelectionPurpose, PendingEffectChoice, PlayerRef,
};
use crate::eternal_cards_v1::e3::{E3ChoiceKindV1, E3ChoiceV1};
use crate::eternal_cube_c1a_v1::C1aChoiceV1;
use crate::eternal_vintage_e7b_v1::dredge;
use crate::event::{self, CommittedEvent};
use crate::event_history_v1::EventKindV1;
use crate::state::{GameState, StackSourceContractV4, Target, Zone};

fn source(state: &GameState, pending: &EffectContinuation) -> Option<SourceV1> {
    let item = &pending.resolving_item;
    if item.kind != crate::state::StackItemKind::Spell {
        let source = item.v4.ability_source_contract?;
        return (source.source == item.source && source.controller == item.controller)
            .then_some(SourceV1::Ability(source));
    }
    if item.inline_effect.is_some() {
        return None;
    }
    let source = item.v4.source_contract?;
    state.objects.try_get(item.source)?;
    ((!item.is_copy || source.spell_copy_origin.is_some())
        && source.zone == Zone::Stack
        && StackSourceContractV4::capture(state, item.source, source.cast_method) == source)
        .then_some(SourceV1::Spell(source))
}

pub(super) fn selected(
    state: &GameState,
    pending: &EffectContinuation,
) -> Option<(InstructionV1, SourceV1)> {
    let (player, count, _) = occult_draw_root(state, pending)?;
    let drawer = pending.ctx.resolve_player(player, state);
    Some((
        InstructionV1::StagedRootV1 {
            player,
            drawer,
            count,
        },
        source(state, pending)?,
    ))
}

pub(super) fn leaf(
    state: &GameState,
    pending: &EffectContinuation,
    path: &[u16],
    start: usize,
) -> Option<(InstructionV1, SourceV1, Vec<EffectFrame>)> {
    let root = crate::effect::validated_definition_owned_root_effect(state, pending).ok()?;
    let (player, count, tail) =
        crate::effect::staged_draw_site(state, pending, &root, path, start)?;
    if count == 0 {
        return None;
    }
    let drawer = pending.ctx.resolve_player(player, state);
    Some((
        InstructionV1::StagedRootV1 {
            player,
            drawer,
            count,
        },
        source(state, pending)?,
        tail,
    ))
}

/// Leave ordinary draw and dredge histories alone. A Miracle can become the
/// top card after a dredge. Once an instruction has started, its receipts
/// continue to apply even if the first actual draw declines that opportunity.
pub(crate) fn tracks(
    state: &GameState,
    pending: &EffectContinuation,
    drawer: crate::ids::PlayerId,
) -> bool {
    if !cfg!(feature = "eternal-fixtures") {
        return false;
    }
    let item = &pending.resolving_item;
    if state.objects.try_get(item.source).is_some_and(|card| {
        matches!(
            crate::card_def::CARD_DEFS[usize::from(card.card_def)].name,
            "Peer into the Abyss" | "Decree of Pain" | "Sylvan Library"
        )
    }) {
        return true;
    }
    let owner = &state.players[drawer.index()];
    if event::draw_instruction_extra_at_hand_size(state, drawer, 1, 0) > 0
        || (owner.draws_this_turn == 0
            && owner
                .library
                .iter()
                .any(|&card| crate::eternal_legacy_e5b_v1::miracle_cost(state, card).is_some()))
    {
        return true;
    }
    let kinds = [
        EventKindV1::EternalOwnedDrawV1,
        EventKindV1::MiracleDrawSuspendedV1,
    ];
    state
        .engine
        .event_history
        .of_kinds_v2(&kinds)
        .any(|(_, entry)| {
            let recorded = match entry {
                CommittedEvent::MiracleDrawSuspendedV1 { stack_item_id, .. } => stack_item_id,
                CommittedEvent::EternalOwnedDrawV1 { journal } => match journal.as_ref() {
                    JournalV1::DrawAttemptV1 { item, .. }
                    | JournalV1::DrawInputBatchV1 { item, .. }
                    | JournalV1::GeneratedDrawV1 { item, .. } => item,
                    _ => return false,
                },
                _ => return false,
            };
            *recorded == item.v4.stack_item_id
        })
}

pub(crate) fn enter_generated(
    state: &mut GameState,
    pending: &EffectContinuation,
    path: &[u16],
    drawer: crate::ids::PlayerId,
) {
    if cfg!(feature = "eternal-fixtures")
        && (dredge::may_need_draw_choice(state, drawer)
            || crate::eternal_legacy_e5b_v1::next_draw_may_offer_miracle(state, drawer))
    {
        super::record(
            state,
            JournalV1::GeneratedDrawV1 {
                item: pending.resolving_item.v4.stack_item_id,
                path: path.to_vec(),
            },
        );
    }
}

pub(crate) fn generated_path<'a>(
    state: &'a GameState,
    pending: &EffectContinuation,
) -> Option<&'a [u16]> {
    state
        .engine
        .event_history
        .of_kinds_v2(&[EventKindV1::EternalOwnedDrawV1])
        .find_map(|(_, entry)| {
            let CommittedEvent::EternalOwnedDrawV1 { journal } = entry else {
                return None;
            };
            let JournalV1::GeneratedDrawV1 { item, path } = journal.as_ref() else {
                return None;
            };
            (*item == pending.resolving_item.v4.stack_item_id).then_some(path.as_slice())
        })
}

/// An attempt is charged once, before the chosen replacement or actual draw.
pub(crate) fn note_attempt(
    state: &mut GameState,
    pending: &EffectContinuation,
    path: &[u16],
    drawer: crate::ids::PlayerId,
) {
    if state.eternal_owned_draw_progress_v1.is_some() || !tracks(state, pending, drawer) {
        return;
    }
    let Ok(root) = crate::effect::validated_definition_owned_root_effect(state, pending) else {
        return;
    };
    let start = attempts(state, pending, path)
        .0
        .unwrap_or(state.engine.event_history.len());
    if crate::effect::draw_site(state, pending, &root, path, start).is_some() {
        super::record(
            state,
            JournalV1::DrawAttemptV1 {
                item: pending.resolving_item.v4.stack_item_id,
                path: path.to_vec(),
            },
        );
    }
}

/// Any current receipt for the item excludes the unmarked compatibility path,
/// including one recorded at a different (possibly tampered) path.
#[cfg(feature = "eternal-fixtures")]
pub(crate) fn unmarked_before(state: &GameState, pending: &EffectContinuation, end: usize) -> bool {
    let item = pending.resolving_item.v4.stack_item_id;
    !state
        .engine
        .event_history
        .of_kinds_v2(&[
            EventKindV1::EternalOwnedDrawV1,
            EventKindV1::MiracleDrawSuspendedV1,
        ])
        .take_while(|(at, _)| *at < end)
        .any(|(_, row)| match row {
            CommittedEvent::MiracleDrawSuspendedV1 { stack_item_id, .. } => *stack_item_id == item,
            CommittedEvent::EternalOwnedDrawV1 { journal } => match journal.as_ref() {
                JournalV1::DrawAttemptV1 { item: owner, .. }
                | JournalV1::GeneratedDrawV1 { item: owner, .. }
                | JournalV1::DrawInputBatchV1 { item: owner, .. } => *owner == item,
                JournalV1::Started(started)
                | JournalV1::StartedWithRiddlerV1 { started, .. }
                | JournalV1::StartedLeafV1 { started, .. } => started.item == item,
                _ => false,
            },
            _ => false,
        })
}

pub(crate) struct AttemptJournal {
    pub first: Option<usize>,
    pub charged: u32,
    pub entered: bool,
}

pub(crate) fn journal_attempts(
    state: &GameState,
    pending: &EffectContinuation,
    path: &[u16],
) -> AttemptJournal {
    let mut first = None;
    let mut entered = false;
    let mut count = 0;
    for (at, row) in state
        .engine
        .event_history
        .of_kinds_v2(&[EventKindV1::EternalOwnedDrawV1])
    {
        let CommittedEvent::EternalOwnedDrawV1 { journal } = row else {
            continue;
        };
        let item = pending.resolving_item.v4.stack_item_id;
        match journal.as_ref() {
            JournalV1::GeneratedDrawV1 {
                item: owner,
                path: site,
            } if *owner == item && site == path => {
                // This marker is after any cost, discard, or other generator
                // and before the first individual draw or replacement.
                first.get_or_insert(at);
                entered = true;
            }
            JournalV1::DrawInputBatchV1 {
                item: owner,
                path: site,
                ..
            } if *owner == item && site == path => {
                entered = true;
            }
            JournalV1::DrawAttemptV1 {
                item: owner,
                path: site,
            } if *owner == item && site == path => {
                first.get_or_insert(at);
                count += 1;
            }
            _ => {}
        }
    }
    AttemptJournal {
        first,
        charged: count,
        entered,
    }
}

pub(crate) fn attempts(
    state: &GameState,
    pending: &EffectContinuation,
    path: &[u16],
) -> (Option<usize>, u32) {
    let AttemptJournal {
        first,
        charged: count,
        entered,
    } = journal_attempts(state, pending, path);
    if entered {
        return (first, count);
    }
    let before = first.unwrap_or(state.engine.event_history.len());
    let (legacy_start, legacy_spent) =
        legacy::visit_attempts(state, pending, path, before, false, |_| {});
    (legacy_start.or(first), count + legacy_spent)
}

pub(crate) fn begin(
    state: &mut GameState,
    pending: &mut EffectContinuation,
    player: PlayerRef,
    count: u32,
    path: &[u16],
) -> Result<bool, String> {
    if count == 0 || state.eternal_owned_draw_progress_v1.is_some() {
        return Ok(false);
    }
    if leaf_starts(state, pending).any(|(_, _, used)| used == path) {
        return Err("Staged draw already started at this path".into());
    }
    let drawer = pending.ctx.resolve_player(player, state);
    let extra = event::draw_instruction_extra(state, drawer, count);
    if extra == 0
        || attempts(state, pending, path).1 != 0
        || !(dredge::owned_draw_needs_stage(state, drawer, count)
            || dredge::may_need_draw_choice(state, drawer))
    {
        return Ok(false);
    }
    // Unopposed printed draws already stop at their own Miracle remainder.
    // Only a replacement choice needs the one-time count stored across answers.
    if !dredge::may_need_draw_choice(state, drawer) {
        let Ok(root) = crate::effect::validated_definition_owned_root_effect(state, pending) else {
            return Ok(false);
        };
        if matches!(
            crate::effect::effect_op_at_structural_path(&root, path),
            Some(
                crate::effect::EffectOp::DrawCards { .. }
                    | crate::effect::EffectOp::DrawCardsDynamic { .. }
            )
        ) {
            return Ok(false);
        }
    }
    let Some((instruction, source, tail)) =
        leaf(state, pending, path, state.engine.event_history.len())
    else {
        return Ok(false);
    };
    if instruction.draw_player(&pending.ctx) != player || pending.frames != tail {
        return Ok(false);
    }
    if instruction.count(state, &pending.ctx) != count {
        return Err("Staged draw changed the count generated at its site".into());
    }
    if path.is_empty() && occult_draw_root(state, pending).is_some() {
        if count != u32::from(pending.ctx.x_value) {
            return Err("Occult Epiphany changed its original draw count".into());
        }
        super::require_new_instruction(state, pending)?;
        start_instruction(state, pending, instruction, source, count, extra);
    } else {
        super::start_with(state, pending, instruction, source, count, |started| {
            JournalV1::StartedLeafV1 {
                started,
                extra,
                path: path.to_vec(),
            }
        });
    }
    Ok(true)
}

pub(super) fn leaf_starts<'a>(
    state: &'a GameState,
    pending: &EffectContinuation,
) -> impl Iterator<Item = (usize, &'a JournalV1, &'a [u16])> {
    let item = pending.resolving_item.v4.stack_item_id;
    state
        .engine
        .event_history
        .of_kinds_v2(&[EventKindV1::EternalOwnedDrawV1])
        .filter_map(move |(at, event)| {
            let CommittedEvent::EternalOwnedDrawV1 { journal } = event else {
                return None;
            };
            let JournalV1::StartedLeafV1 { started, path, .. } = journal.as_ref() else {
                return None;
            };
            (started.item == item).then_some((at, journal.as_ref(), path.as_slice()))
        })
}

/// A started draw can leave its cursor only after completing its attempts.
/// Occult Epiphany additionally binds the discard and its choice or answer.
pub(super) fn validate_idle(
    state: &GameState,
    pending: &EffectContinuation,
) -> Result<bool, String> {
    for (at, journal, path) in leaf_starts(state, pending) {
        let (started, attempts) = journal.start().ok_or("Invalid staged draw start")?;
        let (instruction, source, _) =
            leaf(state, pending, path, at).ok_or("Completed draw lost its original site")?;
        if instruction != started.instruction
            || source != started.source
            || started.total != instruction.count(state, &pending.ctx)
        {
            return Err("Completed staged draw changed its original count or source".into());
        }
        if super::completed_attempts(&state.engine.event_history[at + 1..], at) != Some(attempts) {
            return Err("Staged draw lost its remaining attempts".into());
        }
        if pending.frames.iter().any(|frame| matches!(frame, EffectFrame::Program {
            op: crate::effect::EffectOp::DrawCards { .. } | crate::effect::EffectOp::DrawCardsDynamic { .. },
            path: replay,
        } if replay == path)) {
            return Err("Staged draw replayed its completed instruction".into());
        }
    }
    let Some((instruction, source)) = selected(state, pending) else {
        return Ok(false);
    };
    let item = pending.resolving_item.v4.stack_item_id;
    let mut starts = state
        .engine
        .event_history
        .of_kinds_v2(&[EventKindV1::EternalOwnedDrawV1])
        .filter_map(|(at, entry)| match entry {
            CommittedEvent::EternalOwnedDrawV1 { journal } => match **journal {
                JournalV1::Started(started) | JournalV1::StartedWithRiddlerV1 { started, .. }
                    if started.item == item
                        && matches!(started.instruction, InstructionV1::StagedRootV1 { .. }) =>
                {
                    Some((at, journal))
                }
                _ => None,
            },
            _ => None,
        });
    let Some((started_at, journal)) = starts.next() else {
        return Ok(false);
    };
    let (started, attempts) = journal
        .start()
        .ok_or("Occult Epiphany has an invalid draw start")?;
    if starts.next().is_some()
        || started.instruction != instruction
        || started.source != source
        || started.controller != pending.ctx.controller
        || draw_won_game(state, pending.ctx.controller)
        || state.engine.pending_discard.is_some()
    {
        return Err("Occult Epiphany lost its original draw instruction".into());
    }
    validate_native_progress(
        state,
        &pending.ctx,
        ProgressV1 {
            started_at,
            completed: attempts,
        },
        started,
        attempts,
    )?;
    let (_, _, tail) =
        occult_draw_root(state, pending).ok_or("Occult Epiphany lost its discard")?;
    match (
        &pending.choice,
        pending.frames.as_slice(),
        &pending.answered_choice_guard,
    ) {
        (None, frames, None) if frames == tail => Ok(true),
        (
            Some(PendingEffectChoice::SelectTargets {
                purpose: EffectTargetSelectionPurpose::EternalV1 { choice },
                min_targets,
                ..
            }),
            [],
            None,
        ) if *min_targets == choice.min && discard_choice_matches(state, pending, choice) => {
            Ok(true)
        }
        (
            None,
            [frame @ EffectFrame::EternalSelectionV1 { choice, selected }],
            Some(EffectAnsweredChoiceGuard::StandardSelection { frame: answered }),
        ) if frame == answered.as_ref()
            && discard_choice_matches(state, pending, choice)
            && selected.len() == usize::from(choice.min)
            && selected.iter().enumerate().all(|(index, target)| {
                choice.candidates.contains(target) && !selected[..index].contains(target)
            }) =>
        {
            Ok(true)
        }
        _ => Err("Occult Epiphany retained something other than its discard".into()),
    }
}

fn discard_choice_matches(
    state: &GameState,
    pending: &EffectContinuation,
    choice: &E3ChoiceV1,
) -> bool {
    let controller = pending.ctx.controller;
    let count = pending.ctx.x_value;
    let hand = crate::standard_cards_v1::hand_candidates(state, controller);
    count > 0
        && usize::from(count) < hand.len()
        && choice.kind == E3ChoiceKindV1::C1aV1(C1aChoiceV1::OccultDiscardV1)
        && choice.player == controller
        && choice.bindings == hand
        && choice
            .candidates
            .iter()
            .copied()
            .eq(hand.iter().map(|card| Target::Object(card.object)))
        && choice.min == count
        && choice.max == count
        && !choice.ordered
        && choice.path.is_empty()
        && choice.remaining.is_empty()
}
